function LoginField({ label, htmlFor, children }: { label: string; htmlFor: string; children: ReactNode }) {
  return (
    <>
      <label className="l" htmlFor={htmlFor}>
        {label}
      </label>
      <div className="login-inp">{children}</div>
    </>
  )
}

function PasswordField({
  id,
  value,
  onChange,
}: {
  id: string
  value: string
  onChange: (value: string) => void
}) {
  const [visible, setVisible] = useState(false)

  return (
    <LoginField label="Password" htmlFor={id}>
      <input
        id={id}
        type={visible ? 'text' : 'password'}
        placeholder="Enter your password"
        autoComplete="current-password"
        value={value}
        onChange={(e) => onChange(e.target.value)}
      />
      <button type="button" aria-label={visible ? 'Hide password' : 'Show password'} onClick={() => setVisible((v) => !v)}>
        {visible ? <EyeOff className="size-[17px]" /> : <Eye className="size-[17px]" />}
      </button>
    </LoginField>
  )
}

function LoginCard({
  email,
  password,
  remember,
  busy,
  onEmailChange,
  onPasswordChange,
  onRememberChange,
  onSubmit,
}: {
  email: string
  password: string
  remember: boolean
  busy: boolean
  onEmailChange: (value: string) => void
  onPasswordChange: (value: string) => void
  onRememberChange: (value: boolean) => void
  onSubmit: () => void
}) {
  return (
    <div className="login-form-card">
      <h2>Welcome back</h2>
      <p className="s">Sign in to your TaleemAI CMS account.</p>

      <form
        onSubmit={(e) => {
          e.preventDefault()
          onSubmit()
        }}
      >
        <LoginField label="Email" htmlFor="login-email">
          <input
            id="login-email"
            type="email"
            placeholder="name@yourorganization.com"
            autoComplete="email"
            value={email}
            onChange={(e) => onEmailChange(e.target.value)}
          />
          <Mail className="ei pointer-events-none size-[17px]" aria-hidden />
        </LoginField>

        <PasswordField id="login-password" value={password} onChange={onPasswordChange} />

        <div className="login-row">
          <label>
            <Checkbox checked={remember} onCheckedChange={(checked) => onRememberChange(checked === true)} />
            Remember me
          </label>
          <button
            type="button"
            className="text-[#1a73e8] font-medium hover:underline"
            onClick={() => toast.message('Ask a platform administrator to reset your password.')}
          >
            Forgot password?
          </button>
        </div>

        <button className="login-btn primary" type="submit" disabled={busy || !email || !password}>
          {busy ? <Loader2 className="size-[18px] animate-spin" /> : null}
          Continue
          <svg viewBox="0 0 24 24" aria-hidden>
            <path d="M5 12h14M13 6l6 6-6 6" />
          </svg>
        </button>
      </form>

      <div className="login-or">OR</div>

      <button
        className="login-btn ms"
        type="button"
        onClick={() => toast.message('Microsoft sign-in is not configured for this portal yet.')}
      >
        <i aria-hidden>
          <b style={{ background: '#f25022' }} />
          <b style={{ background: '#7fba00' }} />
          <b style={{ background: '#00a4ef' }} />
          <b style={{ background: '#ffb900' }} />
        </i>
        Sign in with Microsoft
      </button>
    </div>
  )
}

export function LoginPage() {
  const navigate = useNavigate()
  const { login, signOut } = useAuth()
  const [email, setEmail] = useState('')
  const [password, setPassword] = useState('')
  const [remember, setRemember] = useState(true)
  const [busy, setBusy] = useState(false)

  async function submit() {
    if (!email || !password || busy) return
    setBusy(true)
    try {
      const session = await login(email.trim(), password)
      if (roleFrom(session) !== APP_ROLE) {
        signOut()
        toast.error('This portal is for platform administrators only.')
        return
      }
      navigate(APP_HOME)
    } catch (error) {
      toast.error(errorMessage(error))
    } finally {
      setBusy(false)
    }
  }

  return (
    <div className="login-page">
      <div className="login-shell">
        <BrandPanel />

        <section className="login-right">
          <div className="login-mobile-bar">
            <BrandMark compact />
            <ThemeToggle />
          </div>

          <div className="login-top">
            <span>
              Simple<i>•</i>Smart<i>•</i>Scalable
            </span>
            <ThemeToggle />
          </div>

          <LoginCard
            email={email}
            password={password}
            remember={remember}
            busy={busy}
            onEmailChange={setEmail}
            onPasswordChange={setPassword}
            onRememberChange={setRemember}
            onSubmit={() => void submit()}
          />

          <p className="login-new">
            New to TaleemAI CMS?{' '}
            <button type="button" onClick={() => toast.message('Contact your platform administrator for access.')}>
              Contact your administrator.
            </button>
          </p>

          <div className="login-foot">
            <span>© 2026 Taleem AI. All rights reserved.</span>
            <nav>
              <button type="button" onClick={() => toast.message('Privacy policy coming soon.')}>
                Privacy
              </button>
              <button type="button" onClick={() => toast.message('Terms of use coming soon.')}>
                Terms
              </button>
              <button type="button" onClick={() => toast.message('Contact support via your platform administrator.')}>
                Support
              </button>
            </nav>
          </div>
        </section>
      </div>
    </div>
  )
}
